  const ids = new Set(), seen = (kind, id) => { if (!isId(id)) p.push(`${kind}: missing id`); else if (ids.has(kind + ":" + id)) p.push(`${kind} ${id}: duplicate id`); else ids.add(kind + ":" + id); };
